// visualization.js
import { showImage } from './chatbox.js';
import Chart from "chart.js/auto";

// Array to store charts
var allChartsThatWeHaveSaved = [];

// Function to create the line chart
export async function createLineChart() {
  let data;
  let args;

  try {
    const fetched_data = await fetchData();
    data = fetched_data.data;
    args = fetched_data.args;
  } catch (error) {
    console.log(error);
    return;
  }

  // Extract the feature names from args (dynamic)
  const featureNameX = args.visualization.data.x; // Use this to get the 'x' feature name
  const featureNameY = args.visualization.data.y; // Use this to get the 'y' feature name

  // Map the data based on feature names dynamically
  const labels = data.map(item => item[featureNameX]); // This dynamically refers to the feature name for 'x'
  const values = data.map(item => item[featureNameY]); // This dynamically refers to the feature name for 'y'

  // Create the chart with the mapped data
  const ctx = document.getElementById('viz').getContext('2d');
  new Chart(ctx, {
    type: args.visualization.type || 'bar', // Default to bar chart if type is not specified
    data: {
      labels: labels,
      datasets: [{
        label: args.visualization.title || 'Data Visualization', // Default title if none exists
        data: values,
        backgroundColor: 'rgba(75, 192, 192, 0.6)', // Color can also be dynamic from args.visualization.data.color
      }]
    },
    options: {
      responsive: true,
      scales: {
        y: { beginAtZero: true }
      }
    }
  });
}
